questionvariables.text:
/* Design: candidates are f at both ends and at both stationary points (both inside the interval). Source: original. */
L: [[2,-2,1,3,-3,3],[-2,1,4,5,-1,5],[-2,-1,2,-2,-3,3],[2,0,3,4,-2,4],[-2,0,3,1,-1,5],[2,1,4,-3,-1,5],[2,0,1,6,-2,2],[-2,0,3,2,-2,5],[1,-3,3,-4,-4,5],[-1,0,4,7,-1,5]];
ix: 1+rand(10);
a0: L[ix][1]; p0: L[ix][2]; q0: L[ix][3]; d0: L[ix][4]; L1: L[ix][5]; U1: L[ix][6];
f: expand((a0)*x^3-3*(a0)*((p0)+(q0))/2*x^2+3*(a0)*(p0)*(q0)*x+(d0));
df: diff(f,x);
xs: [L1,p0,q0,U1];
vs: [ev(f,x=L1),ev(f,x=p0),ev(f,x=q0),ev(f,x=U1)];
G: lmax(vs); Lv: lmin(vs);
gi: if vs[1]=G then 1 elseif vs[2]=G then 2 elseif vs[3]=G then 3 else 4;
li: if vs[1]=Lv then 1 elseif vs[2]=Lv then 2 elseif vs[3]=Lv then 3 else 4;
gx: xs[gi]; lx: xs[li];
sv: sort(vs); g2: sv[3]; l2: sv[2];
g2i: if vs[1]=g2 then 1 elseif vs[2]=g2 then 2 elseif vs[3]=g2 then 3 else 4;
l2i: if vs[1]=l2 then 1 elseif vs[2]=l2 then 2 elseif vs[3]=l2 then 3 else 4;
g2x: xs[g2i]; l2x: xs[l2i];
mxi: if a0>0 then 2 else 3; mni: if a0>0 then 3 else 2;
g2loc: if g2i=mxi then 1 else 0; l2loc: if l2i=mni then 1 else 0;
pd: (G-Lv)/8+1;
